    agentName: 'fa',
    agentDescription:
        'Fa CLI agent (flutter_agent_harness) — $provider/${model.id}',
    mailSink: mailSink,
    runner: (userMessage) async {
      final stream = providerStreamFunction(provider, apiKey)(
        model,
