final class TrajectoryContextRecord extends TrajectoryRecord {
  /// Creates a [TrajectoryContextRecord].
  const TrajectoryContextRecord({
    required super.index,
    required super.recordId,
    required this.text,
    this.previewMarkdown,
    this.sourceSeq,
    this.startedAt,
  });

