    );

MessageRecord _assistantRecord(
  String id, {
  String? parentId,
  List<ContentBlock> content = const [TextContent(text: 'answer')],
  Usage? usage,
}) {
  return MessageRecord(
    id: id,
    parentId: parentId,
    timestamp: _at(1),
    message: AssistantMessage(
      content: content,
      api: 'anthropic-messages',
      provider: 'anthropic',
      model: 'claude-test',
      usage:
          usage ??
          const Usage(
            input: 100,
            output: 20,
            cacheRead: 30,
            cacheWrite: 5,
            reasoning: 8,
            totalTokens: 163,
            cost: UsageCost(total: 0.5),
          ),
      stopReason: StopReason.stop,
      timestamp: _at(1),
    ),
  );
}

ToolCall _toolCall(String id, {String name = 'bash'}) =>
    ToolCall(id: id, name: name, arguments: const {'cmd': 'ls'});

MessageRecord _toolResultRecord(
  String id, {
  required String parentId,
  required String callId,
