    test('out-of-range index exits 1 with the bounds message', () async {
      final inspect = await runFaTrajectory([
        'inspect',
        '999',
        fixture.sessionId,
      ]);
      expect(inspect.exitCode, 1);
      expect(
        inspect.stderr,
        contains('trajectory: record out of range: 999 (1..10)'),
