      try {
        final run = await runFaTrajectory([
          'view',
        ], sessionRoot: emptyRoot.path);
        expect(run.exitCode, 1);
        expect(run.stderr, contains('trajectory: no sessions in'));
      } finally {
        emptyRoot.deleteSync(recursive: true);
      }
    });
  });
