    test('view --at N truncates the ledger to the first N rows', () async {
      final run = await runFaTrajectory([
        'view',
        fixture.sessionId,
        '--at',
        '3',
      ]);

      expect(run.exitCode, 0, reason: run.output);
      final rows = run.stdout
