/// The operands collected while walking a trajectory subcommand's
/// arguments: positional words plus the recognized flags.
typedef _TrajectoryOperands = ({
  List<String> positionals,
  bool json,
  int? at,
  String? cwd,
  String? sessionRoot,
  String format,
  String? output,
});

/// Walks the arguments after the verb, collecting positionals and the
/// `--json`/`--at`/`--cwd`/`--session-root`/`--format`/`--output` flags.
_TrajectoryOperands _parseTrajectoryOperands(List<String> args) {
  final positionals = <String>[];
  var json = false;
  int? at;
  String? cwd;
  String? sessionRoot;
  var format = 'atif';
  String? output;
  for (var i = 1; i < args.length; i++) {
    final arg = args[i];
    switch (arg) {
      case '--json':
        json = true;
      case '--cwd' || '--session-root':
        final value = _pathFlagValue(args, arg, i);
        if (arg == '--cwd') {
          cwd = value;
        } else {
          sessionRoot = value;
        }
        i++;
      case '--at':
        at = _atFlagValue(args, i);
        i++;
      case '--format' || '--output':
        final value = _pathFlagValue(args, arg, i);
        if (arg == '--format') {
          format = value;
        } else {
          output = value;
        }
        i++;
      default:
        if (arg.startsWith('-')) {
          throw CliArgsException('unknown argument: $arg');
        }
        if (positionals.length >= 2) {
          throw CliArgsException('unexpected argument: $arg');
        }
        positionals.add(arg);
    }
  }
  return (
    positionals: positionals,
    json: json,
    at: at,
    cwd: cwd,
    sessionRoot: sessionRoot,
    format: format,
    output: output,
  );
}

