        i++;
      default:
        if (arg.startsWith('-')) {
          throw CliArgsException('unknown argument: $arg');
        }
        if (positionals.length >= 2) {
          throw CliArgsException('unexpected argument: $arg');
        }
        positionals.add(arg);
