    return null;
  }
  return {
    if (prompt != null) 'prompt_tokens': prompt,
    if (completion != null) 'completion_tokens': completion,
    if (cached != null) 'cached_tokens': cached,
    if (cost > 0) 'cost_usd': cost,
  };
}

