  final positionals = <String>[];
  var json = false;
  int? at;
  String? cwd;
  String? sessionRoot;
  var format = 'atif';
  String? output;
  for (var i = 1; i < args.length; i++) {
    final arg = args[i];
    switch (arg) {
      case '--json':
        json = true;
      case '--cwd' || '--session-root':
        final value = _pathFlagValue(args, arg, i);
