      expect(
        () => parseCliArgs(['trajectory', 'view', '--output', '/tmp/x']),
        throwsA(isA<CliArgsException>()),
      );
      expect(
        () => parseCliArgs(['trajectory', 'cost', '--format', 'atif']),
        throwsA(isA<CliArgsException>()),
      );
    });

