void _validateTrajectoryVerb(String verb, List<String> positionals, int? at) {
  if (verb == 'inspect') {
    if (positionals.isEmpty) {
      throw const CliArgsException(
        'usage: fa trajectory inspect <recordNumber> [sessionId]',
      );
